contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: we take amount and unlockTime as inputs
    function run(uint amount, uint unlockTime) public payable {
        // ensure this contract has enough ETH to send amount to c
        require(address(this).balance >= amount);

        // read before-values via public getters
        // Acc is public mapping; its getter has signature Acc(address) returns (uint unlockTime, uint balance)
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // perform the Put call, sending amount wei
        bool reverted;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If the Put call did not revert, then the contract balance must have increased by exactly amount
        // and the holder balance must have increased by exactly amount, and the stored unlockTime should be
        // max(unlockTime, block.timestamp) but we cannot read block.timestamp here deterministically in assertion.
        // We assert the invariant relating balances and contract balance when the call succeeds.
        assert(
            reverted
            ? true
            : (afterContractBal == beforeContractBal + amount
               && afterBalance == beforeBalance + amount)
        );
    }

    // allow receiving ETH to fund tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will first fund the caller's holder entry via Put, then attempt Collect.
    // Parameters: fund (amount to deposit with Put), unlockTime for the deposit, collectAmt to attempt to withdraw.
    function run(uint fund, uint unlockTime, uint collectAmt) public payable {
        // Ensure this contract has enough ETH to fund the deposit to c
        require(address(this).balance >= fund);

        // Read before-values for this test contract's holder entry
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Perform Put to ensure there is some balance and an unlockTime possibly in the past/future
        bool putReverted;
        try c.Put{value: fund}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // After Put, read current holder state
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Now attempt Collect of collectAmt (may revert). Capture whether it reverts.
        bool collectReverted;
        try c.Collect{value: 0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect succeeded then (1) the holder's balance decreased by collectAmt and
        // (2) the contract's ETH balance decreased by collectAmt.
        // We require that Put may have succeeded or failed; Collect's success implies the decrease.
        assert(
            collectReverted
            ? true
            : (midBalance >= collectAmt && afterBalance + collectAmt == midBalance && midContractBal >= collectAmt && afterContractBal + collectAmt == midContractBal)
        );
    }

    // Allow this test contract to receive ETH so it can fund Put
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that a successful Put call cannot decrease the contract balance and that
    // the caller's recorded balance does not fall below previous+sent when Put succeeds.
    // Parameters: amount to send, unlockTime to pass to Put.
    function run(uint amount, uint unlockTime) public payable {
        // ensure this test contract can fund the deposit
        require(address(this).balance >= amount);

        // Observe before-values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Call Put and capture whether it reverted
        bool putReverted;
        try c.Put{value: amount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Observe after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Put succeeded then: (A) contract's balance did not decrease, (B) recorded balance is at least beforeBal + amount
        // If Put reverted then no guarantees (we accept any outcome). This is a general invariant about non-reverting Put.
        assert(putReverted ? true : (afterContractBal >= beforeContractBal && afterBal >= beforeBal + amount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test Collect: when Collect succeeds (does not revert) it must deduct `amt` from both
    // the contract's ETH balance and from Acc[this].balance; otherwise it reverts.
    // Parameters: amt to attempt to collect.
    function run(uint amt) public payable {
        // Ensure the test contract can fund a prior Put deposit of at least MinSum and amt.
        // We will first deposit `fund` into c so that Collect has a chance to succeed.
        // fund must be >= c.MinSum() and >= amt. Also we must have enough balance here.
        uint min = c.MinSum();
        // require a reasonable bound: avoid underflow; require this contract can send the funds
        uint fund = min >= amt ? min : amt;
        require(address(this).balance >= fund);

        // Make a Put so that Acc[this] has balance >= fund and unlockTime is now (so Collect can succeed
        // only if block.timestamp > unlockTime; we set unlock to 0 via Put fallback or Put with 0 -> sets to now)
        // Use try/catch to observe if Put reverts.
        bool putReverted;
        try c.Put{value: fund}(0) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read before-values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Try Collect and record whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(amt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Assertion: If Collect succeeded then the contract balance decreased exactly by amt
        // and the recorded balance decreased exactly by amt. If Collect reverted then we don't require those.
        assert(collectReverted ? true : (beforeContractBal >= afterContractBal && beforeContractBal - afterContractBal == amt && beforeBal >= afterBal && beforeBal - afterBal == amt));
    }

    // Allow receiving ETH so this test can fund deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function. We take `fund` to deposit and `amt` to attempt to Collect.
    // The function is payable so the caller can fund this test contract when running.
    function run(uint amt, uint fund) public payable {
        require(address(this).balance >= fund);

        // fund must be at least c.MinSum() to allow Collect to succeed later when appropriate
        uint min = c.MinSum();
        if (fund < min) {
            // ensure we deposit at least MinSum so that Collect has a chance to succeed
            fund = min;
            require(address(this).balance >= fund);
        }

        // Make a Put so this contract becomes a holder; use unlock=0 so contract sets unlockTime to now
        bool putReverted;
        try c.Put{value: fund}(0) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read before-values via public getter
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(amt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect returned (did not revert) then both the contract's balance and the recorded holder balance
        // must have decreased by exactly amt. Otherwise no requirement.
        assert(collectReverted ? true : (beforeContractBal >= afterContractBal && beforeContractBal - afterContractBal == amt && beforeBal >= afterBal && beforeBal - afterBal == amt));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an amount to send and an unlock time; this function will call Put and then assert the invariants.
    function run(uint _unlockTime, uint amount) public payable {
        // require we can send the requested amount from this contract to c
        require(address(this).balance >= amount);

        // Read observable before-values
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        // Call Put sending `amount` wei
        bool reverted;
        try c.Put{value: amount}(_unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable after-values
        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // If the call did not revert then the on-chain balance and stored balance must have increased by exactly amount,
        // and the stored unlockTime must be set to either the provided _unlockTime (if > block.timestamp) or block.timestamp.
        // If it reverted then none of the observable post-values should reflect a successful deposit.
        assert(
            // either reverted and nothing changed
            (reverted && afterBalance == beforeBalance && afterContractBalance == beforeContractBalance && afterUnlockTime == beforeUnlockTime)
            ||
            // or not reverted and balances increased by amount and unlockTime updated consistently
            (!reverted && afterBalance == beforeBalance + amount && afterContractBalance == beforeContractBalance + amount && (afterUnlockTime == (_unlockTime > block.timestamp ? _unlockTime : block.timestamp)))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will first deposit funds into c for this contract so Collect can be attempted.
    // Parameters: initial deposit amount to Put, unlockTime to set for the deposit, and amount to attempt to Collect.
    function run(uint _unlockTime, uint depositAmount, uint _am) public payable {
        // require this test contract has enough balance to send the deposit
        require(address(this).balance >= depositAmount);

        // Ensure MinSum requirement: read MinSum and require depositAmount >= MinSum so the deposit can later be collected
        uint min = c.MinSum();
        require(depositAmount >= min);

        // Read before-values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Put depositAmount into c, setting unlock time
        // This call may revert; let it revert (we don't catch) because if it reverts the test will not reach the final assert.
        c.Put{value: depositAmount}(_unlockTime);

        // After successful Put, require that now stored balance increased by depositAmount and contract balance increased accordingly.
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Now ensure time has progressed enough so Collect can succeed: require midUnlock < block.timestamp or set _unlockTime accordingly.
        // We cannot advance time, so require that midUnlock < block.timestamp so Collect can be allowed by the contract.
        require(block.timestamp > midUnlock);

        // Ensure we attempt to collect at most the recorded balance to make success possible
        require(_am <= midBal);

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect{value:0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect succeeded then recorded balance must have decreased by exactly _am and contract balance must have decreased by at least _am.
        // If Collect reverted then nothing is required by this property (we don't assert behavior on revert case).
        assert(reverted || (afterBal + _am == midBal && midContractBal >= afterContractBal && midContractBal - afterContractBal >= _am));
    }

    // Allow receiving ETH so this test contract can fund deposits
    receive() external payable {}
}

