contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to exercise Collect: first deposit enough so Collect can potentially succeed,
    // then attempt Collect and check that on success the recorded balance and contract
    // balance reflect the withdrawal of _am.
    function run(uint unlockTime, uint depositAmount, uint withdrawAmount) public payable {
        // Ensure this test contract can send depositAmount to c
        require(address(this).balance >= depositAmount);

        // Read before-values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Deposit funds to allow Collect to succeed later
        bool putReverted;
        try c.Put{value: depositAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Now attempt Collect(withdrawAmount)
        bool collectReverted;
        try c.Collect{value: 0}(withdrawAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General property:
        // If Collect succeeded (did not revert) then:
        // 1) beforeBal + depositAmount >= withdrawAmount (precondition for successful withdraw),
        // 2) the recorded balance decreased by exactly withdrawAmount (afterBal == beforeBal + depositAmount - withdrawAmount),
        // 3) the contract's balance decreased by at least withdrawAmount (it sent out >= withdrawAmount).
        // We allow putReverted to be true; in that case Collect is expected to revert unless previous funds sufficed.
        assert(collectReverted || (
            (beforeBal + (putReverted ? 0 : depositAmount)) >= withdrawAmount &&
            afterBal == beforeBal + (putReverted ? 0 : depositAmount) - withdrawAmount &&
            beforeContractBal + (putReverted ? 0 : depositAmount) >= afterContractBal + withdrawAmount
        ));
    }

    receive() external payable {}
}
